@log_input_and_output
def add_flags_to_swconfig_with_presence_check(flags, bts_type, connection, local_path='/tmp/swconfig.txt'):
    """
    Adds given flags to swconfig.txt file on SMOD via SSH connection.
    Before adding flags, it checks if flags are already present excluding commented out flags in swconfig.txt file,
    e.g. 0x1003F=1 flag will be added even if swconfig.txt contains #0x1003F=1.
    Swconfig.txt file will be uploaded and BTS reset site will be performed only if any flags were added.
    :param flags: flags which user wants to add, e.g. ['0x590000=9', '0x5800BA=12']
    :type flags: list of str
    :param bts_type: BTS type 5G (GNB) or LTE (ENB)
    :type bts_type: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param local_path: local path where swconfig.txt file will be saved and prepared
    :type local_path: str
    :return: True if any flag has been added, False otherwise
    :rtype: bool
    """
    smod, bts_host = _create_smod_connection(bts_type=bts_type)
    try:
        smod.download_file(local_path=local_path, remote_path='/ffs/run/swconfig.txt')
    except FileNotFoundError:
        log_operation('swconfig.txt file is not found on SMOD. New swconfig.txt file will be created and uploaded...')
        open(local_path, 'w').close()

    upload_and_reset = False
    with open(local_path, 'r+') as sw_config:
        for flag in flags:
            sw_config.seek(0, 0)
            flag_found = any(flag in line and not re.search(rf'#\s*.*{flag}', line) for line in sw_config)
            if not flag_found:
                sw_config.seek(0, 2)
                sw_config.write("\n{0}".format(flag))
                log_result('Flag {0} has been added to swconfig.txt with provided path: {1}'.format(flag, local_path))
                upload_and_reset = True

    if upload_and_reset:
        smod.upload_file(local_path=local_path, remote_path='/ffs/run/swconfig.txt')
        _perform_smod_reset(connection=connection, bts_type=bts_type, bts_host=bts_host, slave=False)
    smod.close_connection()

    return upload_and_reset


