@log_input_and_output
def upload_swconfig(bts_type, connection, swconfig_path=None, reset_site=False, validate_file_name=True):
    """
    Uploads custom swconfig.txt on SMOD. There are three possible strategies to run this method:

        1. Provide path to swconfig absolute path with extension - if so, then specific swconfig
           will be uploaded on SMOD, call example:

           upload_swconfig(swconfig_path=/tmp/custom_swconfig.txt)

        2. Please don't use strategy 2 if You don't know how to implement it, use strategy 1 instead!
           Provide only the name of swconfig file name. Swconfig file will be automatically searched in dedicated
           directory of VM in swconfig/, call example:

           upload_swconfig(swconfig_path=custom_swconfig.txt)

        3. Please don't use strategy 3 if You don't know how to implement it, use strategy 1 instead!
           Don't provide swconfig file and its path. Swconfig file will be automatically searched in dedicated
           directory of VM in swconfig/ and picked based on current BTS sw stream, call example:

           upload_swconfig()

    :param bts_type: BTS type 5G (GNB) or LTE (ENB)
    :type bts_type: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param swconfig_path: depending on strategy it can be the:
                          - absolute path to swconfig.txt, e.g. /tmp/swconfig.txt (Strategy 1)
                          - file name of swconfig, e.g. custom_swconfig.txt (Startegy 2)
                          - None - default (Startegy 3)
    :type swconfig_path: str
    :param validate_file_name: (Optional) Defines if provided file name should be validated
    :param validate_file_name: (Default: True) bool
    :param reset_site: defines if user wants to perform BTS reset site after adding flags to swconfig.txt
    :type reset_site: bool
    """

    if not os.path.isfile(str(swconfig_path)):
        file_name = get_swconfig_file_name(file_name=swconfig_path, validate_file_name=validate_file_name,
                                           bts_type=bts_type)
        swconfig_path = os.path.join(get_path_to_swconfig_dir(bts_type=bts_type), file_name)

    if TestLine().is_full_rack(bts_type=bts_type):
        log_to_console(f"Detected full rack! Uploading {swconfig_path.split('/')[-1]} to {bts_type} slave SMOD ...")
        _upload_swconfig(swconfig_path=swconfig_path, reset_site=reset_site, bts_type=bts_type,
                         slave=True, connection=connection)

    log_to_console(f"Uploading {swconfig_path.split('/')[-1]} to {bts_type} SMOD ...")
    _upload_swconfig(swconfig_path=swconfig_path, reset_site=reset_site, bts_type=bts_type, connection=connection)


def verify_swconfig_flags(flags, bts_type='GNB'):
    """
    Verify if /run/ffs/swconfig.txt file on BTS contains all provided flags.

    :param flags: flags which user wants to verify with current swconfig.txt file e.g.  '0x590000=9' or ['0x590000=9', '0x5800BA=12']
    :type flags: str or list
    :param bts_type: BTS type 5G (GNB) or LTE (ENB)
    :type bts_type: str
    :raises Exception: if any of provided flags is not present in swconfig.txt file
    """
    flags = convert_to_list(flags)
    smod, _ = _create_smod_connection(bts_type=bts_type)
    try:
        swconfig_flags = smod.execute('cat /ffs/run/swconfig.txt')
        list_of_flags = _parse_swconfig(swconfig_flags)
        not_matched = [flag for flag in flags if not any(flag.replace(' ', '') == f'{sw_flag[0]}={sw_flag[1]}' for sw_flag in list_of_flags)]
        if not_matched:
            raise MissingSwconfigFlag(f"Flag(s) {not_matched} not present in swconfig:\n{swconfig_flags})")
    finally:
        smod.close_connection()


@log_input_and_output
def _add_flag_to_swconfig(flag, bts_type, connection, local_path='/tmp/swconfig.txt', reset_site=False):
    """
    Adds particular flag to swconfig.txt file on DU device via SSH connection.
    :param flag: flag user wants to add
    :type flag: str
    :param bts_type: BTS type 5G (GNB) or LTE (ENB)
    :type bts_type: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param local_path: local path where swconfig.txt file will be saved and prepared
    :type local_path: str
    :param reset_site: defines if user wants to perform BTS reset site after adding flags to swconfig.txt
    :type reset_site: bool
    """

    smod, bts_host = _create_smod_connection(bts_type=bts_type)
    smod.download_file(local_path=local_path, remote_path='/ffs/run/swconfig.txt')
    with open(local_path, 'r+') as sw_config:
        flag_found = any(flag in line for line in sw_config)
        if not flag_found:
            sw_config.seek(0, os.SEEK_END)
            sw_config.write("\n{0}\n".format(flag))
    smod.upload_file(local_path=local_path, remote_path='/ffs/run/swconfig.txt')
    log_result('Flag {0} has been added to swconfig.txt with provided path: {1}'.format(flag, local_path))

    if reset_site:
        _perform_smod_reset(connection=connection, bts_type=bts_type, bts_host=bts_host, slave=False)
    smod.close_connection()


@log_input_and_output
def _add_flags_to_swconfig(flags, bts_type, connection, local_path='/tmp/swconfig.txt', reset_site=False):
    """
    Adds particular flags to swconfig.txt file on SMOD via SSH connection.
    :param flags: flags which user wants to add
    :type flags: list
    :param bts_type: BTS type 5G (GNB) or LTE (ENB)
    :type bts_type: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param local_path: local path where swconfig.txt file will be saved and prepared
    :type local_path: str
    :param reset_site: defines if user wants to perform BTS reset site after adding flags to swconfig.txt
    :type reset_site: bool
    """

    smod, bts_host = _create_smod_connection(bts_type=bts_type)
    smod.download_file(local_path=local_path, remote_path='/ffs/run/swconfig.txt')
    with open(local_path, 'r+') as sw_config:
        for flag in flags:
            sw_config.seek(0, 0)
            flag_found = any(flag in line for line in sw_config)
            if not flag_found:
                sw_config.seek(0, 2)
                sw_config.write("\n{0}".format(flag))
                log_result('Flag {0} has been added to swconfig.txt with provided path: {1}'.format(flag, local_path))
    smod.upload_file(local_path=local_path, remote_path='/ffs/run/swconfig.txt')

    if reset_site:
        _perform_smod_reset(connection=connection, bts_type=bts_type, bts_host=bts_host, slave=False)
    smod.close_connection()


@log_input_and_output
def _remove_flag_from_swconfig(flag, bts_type, connection, local_path='/tmp/swconfig.txt', reset_site=False):
    """
    Removes particular flag from swconfig.txt file on SMOD via SSH connection.
    :param flag: flag user wants to remove
    :type flag: str
    :param bts_type: BTS type 5G (GNB) or LTE (ENB)
    :type bts_type: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param local_path: local path where swconfig.txt file will be saved and prepared
    :type local_path: str
    :param reset_site: defines if user wants to perform BTS reset site after removing flags from swconfig.txt
    :type reset_site: bool
    """

    smod, bts_host = _create_smod_connection(bts_type=bts_type)
    smod.download_file(local_path=local_path, remote_path='/ffs/run/swconfig.txt')
    with open(local_path, "r+") as sw_config:
        content = sw_config.readlines()
        sw_config.seek(0)
        for line in content:
            if line.strip() != flag:
                sw_config.write(line)
        sw_config.truncate()
    smod.upload_file(local_path=local_path, remote_path='/ffs/run/swconfig.txt')
    log_result('Flag {0} has been removed from swconfig.txt with provided path: {1}'.format(flag, local_path))

    if reset_site:
        _perform_smod_reset(connection=connection, bts_type=bts_type, bts_host=bts_host, slave=False)
    smod.close_connection()


@log_input_and_output
def _remove_flags_from_swconfig(flags, bts_type, connection, local_path='/tmp/swconfig.txt', reset_site=False):
    """
    Removes particular flag from swconfig.txt file on SMOD via SSH connection.
    :param flags: flags user wants to remove
    :type flags: list
    :param bts_type: BTS type 5G (GNB) or LTE (ENB)
    :type bts_type: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param local_path: local path where swconfig.txt file will be saved and prepared
    :type local_path: str
    :param reset_site: defines if user wants to perform BTS reset site after removing flags from swconfig.txt
    :type reset_site: bool
    """

    smod, bts_host = _create_smod_connection(bts_type=bts_type)
    smod.download_file(local_path=local_path, remote_path='/ffs/run/swconfig.txt')
    with open(local_path, "r+") as sw_config:
        content = sw_config.readlines()
        sw_config.seek(0)
        for line in content:
            if line.strip() not in flags:
                sw_config.write(line)
        sw_config.truncate()
    smod.upload_file(local_path=local_path, remote_path='/ffs/run/swconfig.txt')
    log_result('Flag {0} has been removed from swconfig.txt with provided path: {1}'.format(flags, local_path))

    if reset_site:
        _perform_smod_reset(connection=connection, bts_type=bts_type, bts_host=bts_host, slave=False)
    smod.close_connection()


@log_input_and_output
def _upload_swconfig(swconfig_path, bts_type, connection, slave=False, reset_site=False):
    """
    Uploads custom swconfig.txt file on SMOD via SSH connection.
    :param swconfig_path: local path to custom swconfig.txt that will be uploaded
    :type swconfig_path: str
    :param bts_type: BTS type 5G (GNB) or LTE (ENB)
    :type bts_type: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param slave: defines if user wants to upload swconfig.txt to slave SMOD
    :type slave: bool
    :param reset_site: defines if user wants to perform BTS reset site after uploading custom swconfig.txt to SMOD
    :type reset_site: bool
    """
    bts_procedural_state = get_bts_procedural_state(connection=connection)
    smod, bts_host = _create_smod_connection(bts_type=bts_type, slave=slave)

    smod.upload_file(local_path=swconfig_path, remote_path='/ffs/run/swconfig.txt')
    log_result('Custom swconfig have been uploaded successfully to SMOD')

    if reset_site and (not slave or slave and bts_procedural_state == "NotCommissioned"):
        _perform_smod_reset(connection=connection, bts_type=bts_type, bts_host=bts_host,
                            slave=slave)
    smod.close_connection()


def _create_smod_connection(bts_type, slave=False):
    smod = Smod()

    if bts_type == "ENB" and TestLine().get_bts_setup_mode() == "NSA" or slave:
        vm_ssh_credentials = TestLine().get_bts_test_pc_credentials(bts_type=bts_type, slave=slave)

    if slave:
        credentials = get_ssh_connection_credentials(bts_type=bts_type, common_unit_id=1)
        is_reachable, reachable_slave_ip = wait_for_site(ip=credentials['host'], bts_type=bts_type, slave=True,
                                                         timeout=60, ssh_credentials=vm_ssh_credentials)
        if is_reachable:
            credentials['host'] = reachable_slave_ip
    else:
        credentials = get_ssh_connection_credentials(bts_type=bts_type)
    proxy = None

    if bts_type == "ENB" and TestLine().get_bts_setup_mode() == "NSA" or slave:
        proxy = 'remote_full_rack_half_vm' if slave else 'remote_lte_vm'

        ssh().connect_to(hostname=vm_ssh_credentials['host'], username=vm_ssh_credentials['user'],
                         password=vm_ssh_credentials['password'], alias=proxy)

    smod.connect_to(address=credentials['host'], username=credentials['username'], password=credentials['password'],
                    proxy=proxy, alias=None)

    return smod, credentials['host']


def _perform_smod_reset(connection, bts_type, bts_host, slave):
    connection = _connect_to_second_half_of_full_rack(bts_type=bts_type, bts_host=bts_host) if slave else connection

    log_operation(f"Performing {'slave ' if slave else ''}SMOD reset ...")
    admin().reset_site(connection=connection, timeout=600, detailed_output=True)

    if slave:
        admin().teardown_admin(connection=connection)


def _connect_to_second_half_of_full_rack(bts_type, bts_host):
    vm_credentials = TestLine().get_bts_test_pc_credentials(bts_type=bts_type, slave=True)
    alias = "second_half_of_full_rack"

    log_operation("Connecting via admin to second half of full rack ...")
    admin().setup_admin(bts_host=bts_host,
                        remote_host=vm_credentials['host'],
                        remote_host_username=vm_credentials['user'],
                        remote_host_password=vm_credentials['password'],
                        name=alias)
    return alias


def _parse_swconfig(swconfig_flags):
    """
    Parse the swconfig.txt file returned by the cat command execution and return a list of flags.

    :param swconfig_flags: swconfig.txt file content returned by the 'cat' command execution
    :type swconfig_flags: str
    :return: list of tuples with flags and their values e.g. [('0x590000', '9'), ('0x5800BA', '12')]
    """
    flags = []
    for line in swconfig_flags.splitlines():
        line = line.replace(' ', '')
        if line.startswith("0x"):
            flag, value = re.search(r'^(0x[^=]*)=(\w+)', line).groups()
            flags.append((flag, value))
    return flags
